export const text=(lang:Lang)=>lang==='ru'?ruText:enText;
export const otherImportText=(lang:Lang)=>lang==='ru'?'Импортируйте HTTPS-подписку вручную в совместимый клиент.':'Import the HTTPS subscription manually into a compatible client.';
export const link=(path:string,lang:Lang)=>(isMiniApp()?'/mini-app':'')+path+(lang==='en'?'?lang=en':'');
export const loginRedirect=(lang:Lang)=>{if(isMiniApp())endMiniSession();else location.replace(link('/login',lang));};
export function errorText(error:unknown,lang:Lang){const t=text(lang);const e=error as {status?:number;code?:string;retryAfter?:number};if(e.code==='PAYMENT_REFUND_CONFLICT')return t.refundConflict;if(e.code==='ACCOUNT_ACCESS_BUSY')return t.accessBusy;if(e.status===429)return `${t.rate} ${e.retryAfter||60} ${t.seconds}`;if(e.code==='PLAN_CHANGE_NOT_ELIGIBLE')return t.changePlanUnavailable;if(e.code==='RENEWAL_NOT_ELIGIBLE')return t.renewalUnavailable;if(e.code==='EXTERNAL_BILLING_UNVERIFIED')return t.externalBillingUnavailable;if(e.code==='ACCOUNT_RESTRICTED')return t.restricted;if(e.code==='OPERATOR_ACCOUNT_PROTECTED')return t.restrictionForbidden;if(e.code==='EMAIL_CHANGE_UNAVAILABLE')return t.emailUnavailable;if(e.code==='CURRENT_PASSWORD_INVALID')return t.currentPasswordInvalid;if(e.code==='COMMON_PASSWORD')return t.commonPassword;if(e.status===401)return t.credentials;if(e.status===400)return t.invalid;return t.generic;}
